raw:
{
  "checks": [
    {
      "problem": "链路明细按产品上下分成几块铺开,不同产品的同一步骤不在同一水平线上,读者无法并排对照各产品在同一环节的做法,只能来回滚动查找",
      "A": "解决",
      "B": "没解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "链路明细(按「第N步」分组的各步骤组)",
      "why": "对齐用的是步骤序号,不是环节:各产品步数不同,同一行的第N步常常不是同一件事(北极星第3步是填写乘机人,其余三款第3步是选择舱位;云途的附加产品横跨第4、5两组)。读者要做「同一环节对照」还得先在心里换算步骤号;另外同一款 App 的完整流程被拆散到 9 个步骤组里,想顺着看云途9步、或看某款全程,比 B 里连续一屏看完更费翻找。"
    }
  ],
  "better": "A",
  "reason": "A 把链路明细改成以步骤为行、四款截图排在同一个步骤组里,读者对照同一编号步骤时不用在产品块之间来回滚动;B 仍按产品分块纵铺,同一环节的截图分散在不同区块,只能滚动查找。",
  "next": [
    {
      "where": "链路明细·各步骤组",
      "task": "对照四款在同一环节(附加产品、填写乘机人、确认与支付)的做法",
      "why": "同环节仍散在不同步骤组:云途增值服务在第4步、接送机在第5步,行旅附加产品在第5步,飞鱼附加产品在第5步,北极星没有该环节;读者要逐个步骤组找,只有上面的「关键环节」表是对齐环节的。"
    },
    {
      "where": "链路明细·每个步骤组内的北极星那一行",
      "task": "把北极星与上面三款并排对照同一步骤",
      "why": "北极星每步都掉到该组的第二行,且它的第N步与上面三款的第N步环节不同,按行横读容易误以为四款处在同一环节。"
    },
    {
      "where": "链路明细·单款全流程",
      "task": "顺着看某一款 App 从首页到支付的完整链路",
      "why": "同一款产品的截图被拆到 9 个步骤组里,只能靠小字标题里的产品名辨认,顺着看一款要跨组来回翻。"
    }
  ]
}
